"""JWT helpers for access tokens."""

from datetime import datetime, timedelta, timezone

import jwt
from fastapi import HTTPException

SECRET = "dev-secret-do-not-use-in-prod"  # noqa: S105 — benchmark only
ALGO = "HS256"


def create_token(user_id: int, expires_in_seconds: int = 3600) -> str:
    """Create a signed JWT access token."""
    payload = {
        "user_id": user_id,
        "exp": datetime.now(timezone.utc)
        + timedelta(seconds=expires_in_seconds),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGO)


def decode_token(token: str) -> dict:
    """Decode a signed JWT and return its payload."""
    try:
        return jwt.decode(token, SECRET, algorithms=[ALGO])
    except jwt.InvalidSignatureError as exc:
        raise HTTPException(status_code=401, detail="invalid token signature") from exc


def get_current_user_id(token: str) -> int:
    """Return the user_id claim from a valid token."""
    payload = decode_token(token)
    return payload["user_id"]


def require_admin(token: str) -> int:
    """Ensure the caller is an admin; return the caller's user id."""
    payload = decode_token(token)
    if payload.get("role") != "admin":
        raise HTTPException(status_code=403, detail="admin required")
    return payload["user_id"]

"""In-memory user store and login."""

from copy import deepcopy

from fastapi import HTTPException

from app import auth

_DEFAULT_USERS: dict[int, dict] = {
    1: {"email": "admin@example.com", "password": "adminpass1", "role": "admin"},
    2: {"email": "alice@example.com", "password": "alicepass1", "role": "user"},
    3: {"email": "bob@example.com", "password": "bobpass1", "role": "user"},
}

_USERS: dict[int, dict] = deepcopy(_DEFAULT_USERS)


def get_user(user_id: int) -> dict:
    """Return the user record for ``user_id``."""
    return _USERS[user_id]


def find_user_by_email(email: str) -> tuple[int, dict] | None:
    for uid, u in _USERS.items():
        if u["email"] == email:
            return uid, u
    return None


def login(email: str, password: str) -> str:
    """Verify credentials and return an access token."""
    match = find_user_by_email(email)
    if match is None:
        raise HTTPException(status_code=401, detail="invalid credentials")
    uid, user = match
    if user["password"] != password:
        raise HTTPException(status_code=401, detail="invalid credentials")
    from app import notifications

    notifications.capture_contact(uid, user["email"])
    return auth.create_token(user_id=uid)


def change_email(user_id: int, email: str) -> dict:
    from app import validators

    if not validators.is_valid_email(email) or not email:
        raise HTTPException(status_code=400, detail="invalid email")
    taken = find_user_by_email(email)
    if taken is not None and taken[0] != user_id:
        raise HTTPException(status_code=409, detail="email in use")
    user = get_user(user_id)
    user["email"] = email
    return {"id": user_id, "email": email, "role": user["role"]}


def promote_user(target_id: int) -> dict:
    user = get_user(target_id)
    user["role"] = "admin"
    return user


def reset_store() -> None:
    """Test helper — restore the seeded users."""
    from app import notifications

    _USERS.clear()
    _USERS.update(deepcopy(_DEFAULT_USERS))
    notifications.reset_store()

"""FastAPI app wiring."""

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

from app import (
    auth,
    calculator,
    inventory,
    orders,
    reports,
    users,
    validators,
)


app = FastAPI(title="issue-pilot-benchmark")


class LoginBody(BaseModel):
    email: str
    password: str


class OrderItem(BaseModel):
    sku: str = "widget"
    price: float
    qty: int


class CreateOrderBody(BaseModel):
    items: list[OrderItem]
    coupon: str | None = None


class EmailBody(BaseModel):
    email: str


def _bearer(authorization: str) -> str:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="missing bearer token")
    return authorization.split(" ", 1)[1].strip()


@app.post("/auth/login")
def login(body: LoginBody) -> dict:
    token = users.login(body.email, body.password)
    return {"access_token": token}


@app.get("/auth/me")
def me(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return {"user_id": user_id}


@app.get("/users/{user_id}")
def get_user_endpoint(user_id: int) -> dict:
    user = users.get_user(user_id)
    return {"id": user_id, "email": user["email"], "role": user["role"]}


@app.post("/users/{user_id}/promote")
def promote_endpoint(user_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.require_admin(token)
    user = users.promote_user(user_id)
    return {"id": user_id, "role": user["role"]}


@app.post("/orders")
def create_order_endpoint(
    body: CreateOrderBody,
    authorization: str = Header(...),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    items = [i.model_dump() for i in body.items]
    return orders.create_order(
        user_id=user_id,
        items=items,
        idempotency_key=idempotency_key,
        coupon=body.coupon,
    )


@app.post("/orders/{order_id}/refund")
def refund_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    return orders.refund_order(order_id)


@app.get("/inventory/{sku}")
def stock_endpoint(sku: str) -> dict:
    return {"sku": sku, "stock": inventory.get_stock(sku)}


@app.post("/validate/email")
def validate_email(email: str) -> dict:
    return {"valid": validators.is_valid_email(email)}


@app.get("/calc/sum")
def calc_sum(start: int, end: int) -> dict:
    return {"result": calculator.sum_inclusive(start, end)}


@app.patch("/users/me/email")
def change_email_endpoint(body: EmailBody, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return users.change_email(user_id, body.email)


@app.get("/notifications/inbox")
def inbox_endpoint(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    from app import notifications

    return {"messages": notifications.list_messages(user_id)}


@app.get("/audit/events")
def audit_events_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    from app import audit

    return {"events": audit.events_for_order(order_id)}


@app.get("/reports/sales")
def sales_report_endpoint(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    if users.get_user(user_id).get("role") != "admin":
        raise HTTPException(status_code=403, detail="admin required")
    return reports.build_snapshot()

"""Aggregated storefront totals for staff dashboards."""

from __future__ import annotations

from app import orders, pricing, settings, tax


class Snapshot:
    def __init__(self, merchandise: float, count: int) -> None:
        self.merchandise = merchandise
        self.count = count

    def as_dict(self) -> dict:
        return {"merchandise": self.merchandise, "count": self.count}

    def empty(self) -> bool:
        return self.count == 0


def iter_counted_rows() -> list[dict]:
    return list(orders.list_orders())


def line_amount(item: dict) -> float:
    return float(item.get("price") or 0.0)


def quoted_line(item: dict) -> float:
    return pricing.quote_price(
        str(item.get("sku") or "widget"),
        int(item.get("qty", 1) or 1),
        float(item.get("price") or 0.0),
    )


def merchandise_total(rows: list[dict]) -> float:
    amount = 0.0
    for row in rows:
        for item in row.get("items") or []:
            amount += line_amount(item)
    return round(amount, 2)


def counted_rows() -> list[dict]:
    return iter_counted_rows()


def build_snapshot() -> dict:
    rows = counted_rows()
    merchandise = merchandise_total(rows)
    if settings.flag_enabled("include_tax_in_reports"):
        merchandise = tax.inclusive_total(merchandise)
    snap = Snapshot(merchandise, len(rows))
    return snap.as_dict()


def order_count() -> int:
    return len(counted_rows())


def average_ticket() -> float:
    rows = counted_rows()
    if not rows:
        return 0.0
    return round(merchandise_total(rows) / len(rows), 2)


def sku_units(sku: str) -> int:
    total = 0
    for row in counted_rows():
        for item in row.get("items") or []:
            if str(item.get("sku") or "") == sku:
                total += int(item.get("qty", 1) or 1)
    return total


